import csv, json
from datetime import datetime, timedelta

LIMIT = 60
START, END = "14:00", "22:00"
date = "2026-09-13"

def in_window(ts):
    t = datetime.strptime(ts, "%Y-%m-%d %H:%M")
    if t.strftime("%Y-%m-%d") != date: return False
    hm = t.strftime("%H:%M")
    return START <= hm < END  # 14:00 inclusive, 22:00 exclusive (per-minute rows)

down = {}
with open("data/sensor_log.csv") as f:
    for row in csv.DictReader(f):
        m = row["machine_id"]
        down.setdefault(m, [])
        if row["state"] == "DOWN" and in_window(row["timestamp"]):
            down[m].append(datetime.strptime(row["timestamp"], "%Y-%m-%d %H:%M"))

downtime = {}
for m, times in down.items():
    times.sort()
    total = 0
    # compute consecutive DOWN run lengths
    runs = []
    cur = [times[0]] if times else []
    for t in times[1:]:
        if (t - cur[-1]).total_seconds() == 60:
            cur.append(t)
        else:
            runs.append(cur); cur=[t]
    if cur: runs.append(cur)
    # exclude runs shorter than 4 minutes (micro-stops)
    for r in runs:
        if len(r) >= 4:
            total += len(r)
    downtime[m] = total

over = sorted([m for m,v in downtime.items() if v > LIMIT])
out = {"limit_min": LIMIT, "downtime_by_machine": downtime, "over_limit": over}
json.dump(out, open("output/downtime.json","w"), indent=2)
print(json.dumps(out, indent=2))
